/* Lightweight XLSX parser exposing a SheetJS-like API used by this extension.
 * Supports first worksheet + column extraction needed for bulk messaging.
 */
(function attachXLSX(global) {
  const textDecoder = new TextDecoder();

  function readUint32LE(view, offset) {
    return view.getUint32(offset, true);
  }

  function readUint16LE(view, offset) {
    return view.getUint16(offset, true);
  }

  async function inflateRaw(data) {
    const ds = new DecompressionStream('deflate-raw');
    const writer = ds.writable.getWriter();
    await writer.write(data);
    await writer.close();
    const arrayBuffer = await new Response(ds.readable).arrayBuffer();
    return new Uint8Array(arrayBuffer);
  }

  async function unzip(arrayBuffer) {
    const view = new DataView(arrayBuffer);
    const bytes = new Uint8Array(arrayBuffer);

    // End of central directory record
    let eocdOffset = -1;
    for (let i = bytes.length - 22; i >= Math.max(0, bytes.length - 65558); i -= 1) {
      if (readUint32LE(view, i) === 0x06054b50) {
        eocdOffset = i;
        break;
      }
    }
    if (eocdOffset < 0) throw new Error('Invalid XLSX: EOCD not found');

    const centralDirSize = readUint32LE(view, eocdOffset + 12);
    const centralDirOffset = readUint32LE(view, eocdOffset + 16);
    const entries = new Map();

    let ptr = centralDirOffset;
    const end = centralDirOffset + centralDirSize;

    while (ptr < end) {
      if (readUint32LE(view, ptr) !== 0x02014b50) {
        throw new Error('Invalid XLSX: Bad central directory header');
      }

      const compressionMethod = readUint16LE(view, ptr + 10);
      const compressedSize = readUint32LE(view, ptr + 20);
      const fileNameLen = readUint16LE(view, ptr + 28);
      const extraLen = readUint16LE(view, ptr + 30);
      const commentLen = readUint16LE(view, ptr + 32);
      const localHeaderOffset = readUint32LE(view, ptr + 42);

      const nameStart = ptr + 46;
      const fileName = textDecoder.decode(bytes.slice(nameStart, nameStart + fileNameLen));

      const localSig = readUint32LE(view, localHeaderOffset);
      if (localSig !== 0x04034b50) {
        throw new Error(`Invalid XLSX: Bad local header for ${fileName}`);
      }

      const localNameLen = readUint16LE(view, localHeaderOffset + 26);
      const localExtraLen = readUint16LE(view, localHeaderOffset + 28);
      const fileDataStart = localHeaderOffset + 30 + localNameLen + localExtraLen;
      const fileData = bytes.slice(fileDataStart, fileDataStart + compressedSize);

      let content;
      if (compressionMethod === 0) {
        content = fileData;
      } else if (compressionMethod === 8) {
        content = await inflateRaw(fileData);
      } else {
        throw new Error(`Unsupported compression method ${compressionMethod} in ${fileName}`);
      }

      entries.set(fileName, content);
      ptr += 46 + fileNameLen + extraLen + commentLen;
    }

    return entries;
  }

  function parseSharedStrings(xmlText) {
    const parser = new DOMParser();
    const doc = parser.parseFromString(xmlText, 'application/xml');
    const result = [];
    const sis = doc.getElementsByTagName('si');
    for (const si of sis) {
      const texts = si.getElementsByTagName('t');
      let full = '';
      for (const t of texts) full += t.textContent || '';
      result.push(full);
    }
    return result;
  }

  function parseSheetRows(xmlText, sharedStrings) {
    const parser = new DOMParser();
    const doc = parser.parseFromString(xmlText, 'application/xml');
    const rows = [];

    for (const rowNode of doc.getElementsByTagName('row')) {
      const row = [];
      for (const c of rowNode.getElementsByTagName('c')) {
        const ref = c.getAttribute('r') || 'A1';
        const colLetters = ref.replace(/[0-9]/g, '');
        let col = 0;
        for (let i = 0; i < colLetters.length; i += 1) {
          col = col * 26 + (colLetters.charCodeAt(i) - 64);
        }
        col -= 1;

        const type = c.getAttribute('t');
        const vNode = c.getElementsByTagName('v')[0];
        const raw = vNode ? vNode.textContent || '' : '';

        let value = raw;
        if (type === 's') {
          value = sharedStrings[Number(raw)] || '';
        }

        row[col] = value;
      }
      rows.push(row);
    }

    return rows;
  }

  async function read(arrayBuffer, options = {}) {
    if (options.type !== 'array') {
      throw new Error('Only { type: "array" } is supported');
    }

    const entries = await unzip(arrayBuffer);

    const workbookXml = entries.get('xl/workbook.xml');
    if (!workbookXml) throw new Error('Invalid XLSX: xl/workbook.xml missing');

    const parser = new DOMParser();
    const workbookDoc = parser.parseFromString(textDecoder.decode(workbookXml), 'application/xml');
    const sheets = workbookDoc.getElementsByTagName('sheet');
    const firstName = sheets[0]?.getAttribute('name') || 'Sheet1';

    const sharedStringsXml = entries.get('xl/sharedStrings.xml');
    const sharedStrings = sharedStringsXml
      ? parseSharedStrings(textDecoder.decode(sharedStringsXml))
      : [];

    const sheetXml = entries.get('xl/worksheets/sheet1.xml');
    if (!sheetXml) throw new Error('Invalid XLSX: xl/worksheets/sheet1.xml missing');

    const rows = parseSheetRows(textDecoder.decode(sheetXml), sharedStrings);

    return {
      SheetNames: [firstName],
      Sheets: {
        [firstName]: {
          __rows: rows
        }
      }
    };
  }

  const utils = {
    sheet_to_json(sheet, config = {}) {
      if (!sheet?.__rows) return [];
      if (config.header === 1) return sheet.__rows;
      return sheet.__rows.map((row) => ({ A: row[0] }));
    }
  };

  global.XLSX = { read, utils };
})(self);
